type IEntry = Omit<FcoClause, 'clauseLabel'>;

const s = (clause: IEntry): FcoClause => ({ clauseLabel: 'Section', ...clause });
const r = (clause: IEntry): FcoClause => ({ clauseLabel: 'Rule', ...clause });

